  "help.title": "ひとつ先の夜を、目指して。",
  "help.lead": "最初は短い命でも、その経験は無駄になりません。",
  "help.gatherTitle": "資源を集める",
  "help.gather": "伐採・採掘・採集を選ぶと時間が動き、繰り返し作業します。一時停止後も、作業を選べば再開できます。最初の襲撃は{minutes}分後です。",
  "help.craftTitle": "工房で備える",
  "help.craft": "まずは木材4・石材2で石の槍を製作。装備は完成時に自動装着されます。回復ポーションを工房で製作すると、戦闘中の回復に使えます。食料は救護所で戦闘外に使います。",
  "help.raidTitle": "襲撃を生き延びる",
  "help.raid": "敵が野営地へ攻めてきます。大きな戦闘画面で自動防衛を見守ります。一時停止も可能です。撃退後は元の作業へ戻ります。",
  "help.inheritTitle": "経験を次の命へ",
  "help.inherit": "死亡すると資源・装備・進行レベルは失われます。使った技能の永続経験は残り、次の命の成長を速めます。",
  "help.unlocks": "初めて襲撃を防ぐと村の施設が解放されます。初達成のクエストで継承ポイントを得て、自動化などを解放できます。最初のボスを倒すと外交とオーグメントの3択が登場します。まずは資源・装備・食料の準備に集中しましょう。",
  "help.pause": "いつでも一時停止して計画できます。",
  "help.background": "裏画面でも進みます。設定で自動停止を選べます。ゲームを閉じている間は進みません。",
  "help.return": "野営地に戻る",
